240	// ensures strategy setup, initializes session.
241	func handleLifecycleTurnStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
242		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
243		logging.Info(logCtx, "turn-start",
244			slog.String("event", event.Type.String()),
245			slog.String("session_id", event.SessionID),
246			slog.String("session_ref", event.SessionRef),
247			slog.String("model", event.Model),
248		)
249	
250		sessionID := event.SessionID
251		if sessionID == "" {
252			return fmt.Errorf("no session_id in %s event", event.Type)
253		}
254		if err := validation.ValidateSessionID(sessionID); err != nil {
255			return fmt.Errorf("invalid %s event: %w", event.Type, err)
256		}
257	
258		// Fill model from hint file if the agent didn't provide it on this hook
259		if event.Model == "" {
260			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
261				event.Model = hint
262				logging.Debug(logCtx, "loaded model from hint file",
263					slog.String("model", hint))
264			}
265		}
266	
267		// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)
268		_, captureSpan := perf.Start(ctx, "capture_pre_prompt_state")
269		if err := CapturePrePromptState(ctx, ag, sessionID, event.SessionRef); err != nil {
270			captureSpan.RecordError(err)
271			captureSpan.End()
272			return err
273		}
274		captureSpan.End()
275	
276		// Append prompt to prompt.txt on filesystem so it's available for
277		// mid-turn commits (before SaveStep writes it to the shadow branch).
278		// Prompts are separated by "\n\n---\n\n" to support multiple turns.
279		if event.Prompt != "" {
280			sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
281			if sessionDirAbs, absErr := paths.AbsPath(ctx, sessionDir); absErr == nil {
282				if mkErr := os.MkdirAll(sessionDirAbs, 0o750); mkErr == nil {
283					promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
284					existing, readErr := os.ReadFile(promptPath) //nolint:gosec // session metadata path
285					var content string
286					if readErr == nil && len(existing) > 0 {
287						content = string(existing) + "\n\n---\n\n" + event.Prompt
288					} else {
289						content = event.Prompt
290					}
291					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil { //nolint:gosec // path from internal metadata, not user input
292						logging.Warn(logCtx, "failed to write prompt.txt",
293							slog.String("error", writeErr.Error()))
294					}
295				}
296			}
297		}
298	
299		// Ensure strategy setup and initialize session
300		_, initSpan := perf.Start(ctx, "init_session")
301		if err := strategy.EnsureSetup(ctx); err != nil {
302			logging.Warn(logCtx, "failed to ensure strategy setup",
303				slog.String("error", err.Error()))
304		}
305	
306		strat := GetStrategy(ctx)
307		if err := strat.InitializeSession(ctx, sessionID, ag.Type(), event.SessionRef, event.Prompt, event.Model); err != nil {
308			logging.Warn(logCtx, "failed to initialize session state",
309				slog.String("error", err.Error()))
310		}
311		initSpan.End()
312	
313		if err := maybeInjectMemoryLoop(ctx, ag, event); err != nil {
314			return err
315		}
316	
317		return nil
318	}
