446	func PreviewSelection(snapshot Snapshot, prompt string, now time.Time, opts ...SelectOption) SelectionReport {
447		cfg := &selectConfig{}
448		for _, opt := range opts {
449			opt(cfg)
450		}
451	
452		maxInjected := snapshot.MaxInjected
453		if maxInjected <= 0 {
454			maxInjected = DefaultMaxInjected
455		}
456	
457		promptTokens := tokenize(prompt)
458		if len(promptTokens) == 0 {
459			return SelectionReport{}
460		}
461	
462		candidates := make([]scoredCandidate, 0, len(snapshot.Records))
463		skipped := make([]SkippedMatch, 0, len(snapshot.Records))
464		for _, record := range snapshot.Records {
465			signals := buildRecordMatchSignals(record)
466			primaryOverlap := tokenOverlap(promptTokens, signals.primaryTokens)
467			if !cfg.passesScope(record) {
468				if primaryOverlap > 0 {
469					skipped = append(skipped, SkippedMatch{
470						Record: record,
471						Reason: "scope mismatch",
472					})
473				}
474				continue
475			}
476			if reason, rejected := injectionRejectionReason(record, primaryOverlap); rejected {
477				if primaryOverlap > 0 {
478					skipped = append(skipped, SkippedMatch{
479						Record: record,
480						Reason: reason,
481					})
482				}
483				continue
484			}
485			candidate := buildScoredCandidate(record, primaryOverlap, now)
486			if candidate.adjustedScore <= 0 {
487				skipped = append(skipped, SkippedMatch{
488					Record: record,
489					Reason: "score adjusted below zero",
490				})
491				continue
492			}
493			candidates = append(candidates, candidate)
494		}
495	
496		sort.SliceStable(candidates, func(i, j int) bool {
497			if candidates[i].adjustedScore != candidates[j].adjustedScore {
498				return candidates[i].adjustedScore > candidates[j].adjustedScore
499			}
500			if candidates[i].baseScore != candidates[j].baseScore {
501				return candidates[i].baseScore > candidates[j].baseScore
502			}
503			if candidates[i].record.Strength != candidates[j].record.Strength {
504				return candidates[i].record.Strength > candidates[j].record.Strength
505			}
506			return candidates[i].record.Title < candidates[j].record.Title
507		})
508	
509		matches := packSelectedCandidates(candidates, maxInjected)
510		skipped = append(skipped, explainSkippedCandidates(candidates, matches)...)
511		return SelectionReport{
512			Matches: matches,
513			Skipped: skipped,
514		}
515	}

